import{_ as t,o as s,c as r,ag as o}from"./chunks/framework.-5_vvMqw.js";const p=JSON.parse('{"title":"Skill library","description":"","frontmatter":{},"headers":[],"relativePath":"skills.md","filePath":"skills.md","lastUpdated":1793867766000}'),n={name:"skills.md"};function i(a,e,l,d,h,c){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="skill-library" tabindex="-1">Skill library <a class="header-anchor" href="#skill-library" aria-label="Permalink to &quot;Skill library&quot;">​</a></h1><p>The skill library keeps reusable agent skills — a <code>SKILL.md</code> with instructions, plus helper scripts and other files — for all your sessions. Every save is a new version, and older versions can be restored. Sessions put the matching skills into the agent&#39;s own skill directory and keep it up to date while they run, and agents can search, read and save skills themselves, so what one session works out is there for the next.</p><p><strong>Edition:</strong> Community · Enterprise for sharing with other users, groups or everyone · <strong>Who:</strong> every user for their own skills; admins for sharing and publishing settings</p><h2 id="managing-skills-in-settings" tabindex="-1">Managing skills in Settings <a class="header-anchor" href="#managing-skills-in-settings" aria-label="Permalink to &quot;Managing skills in Settings&quot;">​</a></h2><p>Open <strong>Settings → Skills</strong>. The list shows each skill with its version (<code>v3</code>), its project if it has one, and <em>shared · owner</em> (with the owner&#39;s name) for skills other users shared with you. <strong>Search skills…</strong> filters the list.</p><p><strong>Add skill</strong> opens the form:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>kebab-case: lowercase letters, digits, hyphens, e.g. <code>review-checklist</code></td></tr><tr><td><strong>Description</strong></td><td>When the agent should use it — this is what the agent sees when choosing a skill</td></tr><tr><td><strong>Scope</strong></td><td><strong>Personal (all my sessions)</strong> or <strong>Project:</strong> and the project name — a project skill is only loaded into that project&#39;s sessions</td></tr><tr><td><strong>Content</strong></td><td>The <code>SKILL.md</code> Markdown</td></tr></tbody></table><p><strong>Edit</strong> changes a skill and takes an optional <strong>Change note</strong> for the history. Files that came with the skill (scripts, assets) are listed and kept on save; agents manage them through the library tools. <strong>Delete</strong> removes the skill. Skills shared with you are read-only.</p><h3 id="versions-and-restore" tabindex="-1">Versions and restore <a class="header-anchor" href="#versions-and-restore" aria-label="Permalink to &quot;Versions and restore&quot;">​</a></h3><p><strong>History</strong> lists every version with time, author and change note. <strong>View</strong> shows that version&#39;s content; <strong>Restore</strong> makes it the new latest version, content and files together, so restoring is itself a new version and nothing is lost.</p><h2 id="which-skills-a-session-gets" tabindex="-1">Which skills a session gets <a class="header-anchor" href="#which-skills-a-session-gets" aria-label="Permalink to &quot;Which skills a session gets&quot;">​</a></h2><p>There is no per-session list to manage. A session receives:</p><ul><li>your personal skills,</li><li>the skills of the session&#39;s project, if it has one,</li><li>skills shared with you (Enterprise).</li></ul><p>When two have the same name, the project skill wins over a personal one, and your own skill wins over a shared one.</p><h2 id="skills-stay-in-sync-while-sessions-run" tabindex="-1">Skills stay in sync while sessions run <a class="header-anchor" href="#skills-stay-in-sync-while-sessions-run" aria-label="Permalink to &quot;Skills stay in sync while sessions run&quot;">​</a></h2><p>The session writes its skills into <code>~/.claude/skills</code> at start (Codex, Cursor and OpenClaw read the same directory as <code>~/.agents/skills</code>) and checks the library for changes every minute. A skill saved in Settings or by another session therefore reaches running sessions:</p><table tabindex="0"><thead><tr><th>Agent</th><th>A new or changed skill appears</th></tr></thead><tbody><tr><td>Claude Code</td><td>On the next turn</td></tr><tr><td>Codex</td><td>On the next turn</td></tr><tr><td>OpenCode</td><td>When the agent is idle, before its next turn</td></tr><tr><td>OpenClaw</td><td>At the next start of the session</td></tr><tr><td>Cursor</td><td>Not verified — assume the next start</td></tr></tbody></table><p>If the agent edits a library skill in place, the session keeps its edit rather than overwriting it with the library&#39;s version; the agent is told to save the edit with <code>upload_skill</code> to share it.</p><h3 id="skills-the-agent-creates" tabindex="-1">Skills the agent creates <a class="header-anchor" href="#skills-the-agent-creates" aria-label="Permalink to &quot;Skills the agent creates&quot;">​</a></h3><p>A skill the agent creates as a new directory under <code>~/.claude/skills</code> is imported into the library automatically — within about a minute and when the session ends. It lands in the session&#39;s project, or in your personal library when the session has none. Unchanged skills do not create new versions.</p><h3 id="the-end-of-turn-reminder" tabindex="-1">The end-of-turn reminder <a class="header-anchor" href="#the-end-of-turn-reminder" aria-label="Permalink to &quot;The end-of-turn reminder&quot;">​</a></h3><p>Claude Code, Codex and Cursor sessions get a reminder at the end of a turn that edited files or ran commands: is there a reusable procedure or script that belongs in the library? The agent saves it or says in one line that there is nothing. Turns that only answered a question are left alone.</p><h2 id="the-agent-s-library-tools" tabindex="-1">The agent&#39;s library tools <a class="header-anchor" href="#the-agent-s-library-tools" aria-label="Permalink to &quot;The agent&#39;s library tools&quot;">​</a></h2><p>Every session gets the built-in <code>skill-library</code> MCP server:</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th></tr></thead><tbody><tr><td><code>search_skills</code></td><td>Search project, personal and shared skills by keywords — and by meaning if the operator configured embeddings</td></tr><tr><td><code>get_skill</code></td><td>Read a skill, a single file of it, or an older version; with <code>out_dir</code>, write the whole skill to disk</td></tr><tr><td><code>upload_skill</code></td><td>Create or update a skill, with an optional change note; takes a local <code>path</code> (a directory, a file or a <code>.tar.gz</code>) so large scripts never pass through the agent&#39;s context</td></tr><tr><td><code>list_skill_versions</code></td><td>A skill&#39;s history, newest first</td></tr><tr><td><code>restore_skill_version</code></td><td>Restore an older version of one of your own skills as the new latest</td></tr></tbody></table><p>Uploads go to the session&#39;s project, or to your personal library when the session has no project.</p><h2 id="sharing-skills-enterprise" tabindex="-1">Sharing skills (Enterprise) <a class="header-anchor" href="#sharing-skills-enterprise" aria-label="Permalink to &quot;Sharing skills (Enterprise)&quot;">​</a></h2><p>On the Enterprise edition, admins see <strong>Sharing</strong> on their own skills in Settings → Skills: <strong>Share with everyone</strong>, with selected <strong>Users</strong>, or with <strong>Groups</strong> from your OIDC provider. Recipients get the skill read-only, in Settings and in their sessions.</p><p>Under <strong>Settings → Skill publishing</strong>, an admin can tick <strong>Allow users to publish skills to everyone</strong>. Users then see <strong>Publish to everyone</strong> on their own skills. Without an Enterprise licence these controls show a licence notice instead.</p><h2 id="for-operators" tabindex="-1">For operators <a class="header-anchor" href="#for-operators" aria-label="Permalink to &quot;For operators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Value</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>skillLibrary.mcp</code></td><td><code>true</code></td><td>Give sessions the <code>skill-library</code> MCP server</td></tr><tr><td><code>skillLibrary.embeddings.endpoint</code></td><td><code>&quot;&quot;</code></td><td>An <code>/embeddings</code> HTTP endpoint for search by meaning; empty means keyword search only</td></tr><tr><td><code>skillLibrary.embeddings.model</code></td><td><code>&quot;&quot;</code></td><td>The embedding model to request</td></tr><tr><td><code>skillLibrary.embeddings.apiKey</code></td><td><code>&quot;&quot;</code></td><td>Key for that endpoint</td></tr></tbody></table><p>See <a href="/docs/chart-values">Chart values</a>.</p>',32)])])}const k=t(n,[["render",i]]);export{p as __pageData,k as default};
